and fStarC_TypeChecker_UnivEq_solve_universe_eq (env : FStarC_TypeChecker_Env.env) (umax_heuristic_ok : bool) (defer_ok : bool) (solve : ('w -> ((int * FStarC_Syntax_Syntax.version * FStarC_Range_Type.range) -> (FStarC_Syntax_Syntax.universe -> 'w)))) (st : 'w) (u1 : FStarC_Syntax_Syntax.universe) (u2 : FStarC_Syntax_Syntax.universe) : ('w) FStarC_TypeChecker_UnivEq.univ_eq_sol =
  (let u11 = (fStarC_TypeChecker_Normalize_normalize_universe env u1) in
  let u21 = (fStarC_TypeChecker_Normalize_normalize_universe env u2) in
