      | ((FStarC_Syntax_Syntax.U_max (us1)), (FStarC_Syntax_Syntax.U_max (us2))) -> (let tmp = (FStarC_TypeChecker_UnivEq.solve_universe_eq__filter_out_common_univs us1 us2) in
        (match tmp with
          | (us11, us21) -> (if ((=) ((fun l -> Z.of_int (BatList.length l)) us11) ((fun l -> Z.of_int (BatList.length l)) us21)) then (fStarC_TypeChecker_UnivEq_solve_universe_eq__aux env umax_heuristic_ok defer_ok solve st us11 us21) else (FStarC_TypeChecker_UnivEq.ufailed_thunk (fun tmp1 -> (let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u12) in
            let tmp3 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u22) in
            (FStarC_Format.fmt2 "Unable to unify universes: %s and %s" tmp2 tmp3)))))
        ))
      | ((FStarC_Syntax_Syntax.U_max (us)), u') -> (fStarC_TypeChecker_UnivEq_solve_universe_eq__aux__1 env umax_heuristic_ok defer_ok solve u' st us)
      | (u', (FStarC_Syntax_Syntax.U_max (us))) -> (fStarC_TypeChecker_UnivEq_solve_universe_eq__aux__2 env umax_heuristic_ok defer_ok solve u' st us)
      | tmp -> (FStarC_TypeChecker_UnivEq.ufailed_thunk (fun tmp1 -> (let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u12) in
        let tmp3 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u22) in
        (FStarC_Format.fmt3 "Unable to unify universes: %s and %s (%s)" tmp2 tmp3 msg))))
    ))) in
  (match (u11, u21) with
    | ((FStarC_Syntax_Syntax.U_bvar (tmp)), tmp1) -> (let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u11) in
      let tmp3 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u21) in
      let tmp4 = (FStarC_Format.fmt2 "Impossible: found an de Bruijn universe variable or unknown universe: %s, %s" tmp2 tmp3) in
      (FStarC_Effect.failwith tmp4))
    | (FStarC_Syntax_Syntax.U_unknown, tmp) -> (let tmp1 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u11) in
      let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u21) in
      let tmp3 = (FStarC_Format.fmt2 "Impossible: found an de Bruijn universe variable or unknown universe: %s, %s" tmp1 tmp2) in
      (FStarC_Effect.failwith tmp3))
    | (tmp, (FStarC_Syntax_Syntax.U_bvar (tmp1))) -> (let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u11) in
      let tmp3 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u21) in
      let tmp4 = (FStarC_Format.fmt2 "Impossible: found an de Bruijn universe variable or unknown universe: %s, %s" tmp2 tmp3) in
      (FStarC_Effect.failwith tmp4))
    | (tmp, FStarC_Syntax_Syntax.U_unknown) -> (let tmp1 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u11) in
      let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u21) in
      let tmp3 = (FStarC_Format.fmt2 "Impossible: found an de Bruijn universe variable or unknown universe: %s, %s" tmp1 tmp2) in
      (FStarC_Effect.failwith tmp3))
    | ((FStarC_Syntax_Syntax.U_name (x)), (FStarC_Syntax_Syntax.U_name (y))) -> (if ((=) (FStarC_Ident.string_of_id x) (FStarC_Ident.string_of_id y)) then (FStarC_TypeChecker_UnivEq.USolved (st)) else (FStarC_TypeChecker_UnivEq.ufailed_simple "Incompatible universes"))
    | (FStarC_Syntax_Syntax.U_zero, FStarC_Syntax_Syntax.U_zero) -> (FStarC_TypeChecker_UnivEq.USolved (st))
    | ((FStarC_Syntax_Syntax.U_succ (u12)), (FStarC_Syntax_Syntax.U_succ (u22))) -> (fStarC_TypeChecker_UnivEq_solve_universe_eq env umax_heuristic_ok defer_ok solve st u12 u22)
    | ((FStarC_Syntax_Syntax.U_unif (u__1, u__2, u__3)), (FStarC_Syntax_Syntax.U_unif (u__11, u__21, u__31))) -> (let v1 = (u__1, u__2, u__3) in
