    | ((FStarC_Syntax_Syntax.U_unif (u__1, u__2, u__3)), u) -> (let v1 = (u__1, u__2, u__3) in
      let u3 = (fStarC_TypeChecker_UnivEq_norm_univ env u) in
      let tmp = (FStarC_TypeChecker_UnivEq.solve_universe_eq__occurs_univ v1 u3) in
      (if tmp then (let tmp1 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe (FStarC_Syntax_Syntax.U_unif ((match v1 with (custard_tup, _, _) -> custard_tup), (match v1 with (_, custard_tup, _) -> custard_tup), (match v1 with (_, _, custard_tup) -> custard_tup)))) in
      let tmp2 = (FStarC_Syntax_Print.fStarC_Class_Show_show__universe u3) in
      let tmp3 = (FStarC_Format.fmt2 "Failed occurs check: %s occurs in %s" tmp1 tmp2) in
      (try_umax_components u11 u21 tmp3)) else (let tmp1 = (solve st v1 u3) in
      (FStarC_TypeChecker_UnivEq.USolved (tmp1)))))
    | (u, (FStarC_Syntax_Syntax.U_unif (u__1, u__2, u__3))) -> (let v1 = (u__1, u__2, u__3) in
      let u3 = (fStarC_TypeChecker_UnivEq_norm_univ env u) in
