      (FStarC_TypeChecker_UnivEq.USolved (tmp1)))))
    | ((FStarC_Syntax_Syntax.U_max (tmp)), tmp1) -> (if defer_ok then (FStarC_TypeChecker_UnivEq.UDeferred (st)) else (let u12 = (fStarC_TypeChecker_UnivEq_norm_univ env u11) in
      let u22 = (fStarC_TypeChecker_UnivEq_norm_univ env u21) in
      let tmp2 = (FStarC_Syntax_Util.eq_univs u12 u22) in
      (if tmp2 then (FStarC_TypeChecker_UnivEq.USolved (st)) else (try_umax_components u12 u22 ""))))
    | (tmp, (FStarC_Syntax_Syntax.U_max (tmp1))) -> (if defer_ok then (FStarC_TypeChecker_UnivEq.UDeferred (st)) else (let u12 = (fStarC_TypeChecker_UnivEq_norm_univ env u11) in
      let u22 = (fStarC_TypeChecker_UnivEq_norm_univ env u21) in
      let tmp2 = (FStarC_Syntax_Util.eq_univs u12 u22) in
      (if tmp2 then (FStarC_TypeChecker_UnivEq.USolved (st)) else (try_umax_components u12 u22 ""))))
    | ((FStarC_Syntax_Syntax.U_succ (tmp)), FStarC_Syntax_Syntax.U_zero) -> (FStarC_TypeChecker_UnivEq.ufailed_simple "Incompatible universes")
    | ((FStarC_Syntax_Syntax.U_succ (tmp)), (FStarC_Syntax_Syntax.U_name (tmp1))) -> (FStarC_TypeChecker_UnivEq.ufailed_simple "Incompatible universes")
    | (FStarC_Syntax_Syntax.U_zero, (FStarC_Syntax_Syntax.U_succ (tmp))) -> (FStarC_TypeChecker_UnivEq.ufailed_simple "Incompatible universes")
    | (FStarC_Syntax_Syntax.U_zero, (FStarC_Syntax_Syntax.U_name (tmp))) -> (FStarC_TypeChecker_UnivEq.ufailed_simple "Incompatible universes")
    | ((FStarC_Syntax_Syntax.U_name (tmp)), (FStarC_Syntax_Syntax.U_succ (tmp1))) -> (FStarC_TypeChecker_UnivEq.ufailed_simple "Incompatible universes")
    | ((FStarC_Syntax_Syntax.U_name (tmp)), FStarC_Syntax_Syntax.U_zero) -> (FStarC_TypeChecker_UnivEq.ufailed_simple "Incompatible universes")
  ))

